node -v && node --input-type=module -e "
const zones = ['America/New_York','UTC','Asia/Kathmandu','Pacific/Kiritimati','America/Los_Angeles'];
const samples = [
  '2024-01-01T04:59:59.999Z',
  '2024-01-01T05:00:00.000Z',
  '2024-03-10T04:59:59.999Z',
  '2024-03-10T05:00:00.000Z',
  '2024-03-10T06:59:59.999Z',
  '2024-03-10T07:00:00.000Z',
  '2024-11-03T03:59:59.999Z',
  '2024-11-03T04:00:00.000Z',
  '2024-11-03T05:00:00.000Z',
  '2024-11-03T05:30:00.000Z',
  '2024-11-03T06:00:00.000Z',
  '2024-01-01T00:00:00.000Z',
  '2023-12-31T18:15:00.000Z',
  '2024-01-01T18:15:00.000Z',
];
function ym(iso, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(iso));
  const m = {};
  for (const p of parts) if (p.type !== 'literal') m[p.type] = p.value;
  return m.year + '-' + m.month + '-' + m.day + ' ' + m.hour + ':' + m.minute + ':' + m.second;
}
for (const z of zones) {
  console.log('\\n==', z);
  for (const s of samples) console.log(s, '->', ym(s, z));
}
console.log('\\nhour24 check NY', ym('2024-01-01T05:00:00.000Z', 'America/New_York'));
try { console.log('invalid', new Intl.DateTimeFormat('en-US', { timeZone: 'Not/AZone', year: 'numeric', month: '2-digit' }).format(new Date())); } catch (e) { console.log('invalid tz', e.name, e.message); }
try { console.log('nan', new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', year: 'numeric', month: '2-digit' }).format(new Date(NaN))); } catch (e) { console.log('nan', e.name, e.message); }
"
